glm::vec3 r = pj->position - pi->position;
float dist = glm::length(r);
if (dist <= 0.0f || dist > h) return glm::vec3(0.0f);
r /= dist; // normalize
float pressureTerm = (pi->pressure + pj->pressure) / (2.0f * settings.restDensity);
glm::vec3 pressureForce = -mass * pressureTerm * spikyGrad * (h - dist) * r;
return pressureForce;

